-- Description: Process event id 2 race results

SET search_path TO endurancetrio_hub;

-- Update existing athletes
UPDATE athlete SET year_of_birth = 1960 WHERE id = 4;
UPDATE athlete SET long_name = 'António José Correia Santos' WHERE id = 11;

-- Insert new athletes

SELECT setval('seq_athlete_id', 185, FALSE);

-- Update existing race's result_status
UPDATE race SET result_status = 'INCOMPLETE' WHERE id IN (4, 5, 6);

-- Insert individual results

SELECT setval('seq_individual_result_id', 389, FALSE);
